CREATE TABLE `ContactInquiry` (`id` INTEGER NOT NULL AUTO_INCREMENT,`reference` VARCHAR(32) NOT NULL,`name` VARCHAR(120) NOT NULL,`email` VARCHAR(191) NOT NULL,`subject` VARCHAR(191) NOT NULL,`message` TEXT NOT NULL,`status` ENUM('NEW','READ','IN_PROGRESS','REPLIED','ARCHIVED','SPAM') NOT NULL DEFAULT 'NEW',`priority` ENUM('LOW','NORMAL','HIGH','URGENT') NOT NULL DEFAULT 'NORMAL',`source` VARCHAR(50) NOT NULL DEFAULT 'website',`ipHash` VARCHAR(64) NULL,`userAgent` VARCHAR(500) NULL,`notificationStatus` ENUM('PENDING','SENT','FAILED') NOT NULL DEFAULT 'PENDING',`notificationError` VARCHAR(1000) NULL,`lastRepliedAt` DATETIME(3) NULL,`archivedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `ContactInquiry_reference_key`(`reference`),INDEX `ContactInquiry_status_createdAt_idx`(`status`,`createdAt`),INDEX `ContactInquiry_priority_createdAt_idx`(`priority`,`createdAt`),INDEX `ContactInquiry_email_createdAt_idx`(`email`,`createdAt`),INDEX `ContactInquiry_notificationStatus_idx`(`notificationStatus`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ContactReply` (`id` INTEGER NOT NULL AUTO_INCREMENT,`inquiryId` INTEGER NOT NULL,`adminId` INTEGER NOT NULL,`subject` VARCHAR(191) NOT NULL,`message` TEXT NOT NULL,`deliveryStatus` ENUM('PENDING','SENT','FAILED') NOT NULL DEFAULT 'PENDING',`providerMessageId` VARCHAR(255) NULL,`deliveryError` VARCHAR(1000) NULL,`sentAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `ContactReply_inquiryId_createdAt_idx`(`inquiryId`,`createdAt`),INDEX `ContactReply_adminId_idx`(`adminId`),INDEX `ContactReply_deliveryStatus_idx`(`deliveryStatus`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `ContactReply` ADD CONSTRAINT `ContactReply_inquiryId_fkey` FOREIGN KEY (`inquiryId`) REFERENCES `ContactInquiry`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ContactReply` ADD CONSTRAINT `ContactReply_adminId_fkey` FOREIGN KEY (`adminId`) REFERENCES `Admin`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
